  const response=await context.request.post(base+'/api/auth/register',{headers:{Origin:base},data:{username:name,email:name+'@example.com',password:randomUUID()}});
  assert.equal(response.status(),201);
  const session=await response.json();
  const headers={Origin:base,'X-CSRF-Token':session.csrf_token};
  const page=await context.newPage();
  await page.goto(base+'/upload');
  await page.getByLabel('Название',{exact:true}).fill('Corrupt synthetic fixture');
  await page.getByLabel('Видеофайл',{exact:true}).setInputFiles({name:'corrupt.mp4',mimeType:'video/mp4',buffer:Buffer.from('not a media file')});
  await page.getByRole('button',{name:'Загрузить видео',exact:true}).click();
  await page.getByText(/Статус: Ошибка/).waitFor({timeout:30000});
  assert((await page.locator('section').innerText()).includes('Файл повреждён'));
  const list=await (await context.request.get(base+'/api/me/videos')).json();
  const corrupt=list.items.find(v=>v.title==='Corrupt synthetic fixture');
  assert.equal(corrupt.status,'failed');
  await page.goto(base+'/watch/'+corrupt.id);
  await page.getByRole('alert').filter({hasText:'Видео не найдено или недоступно'}).waitFor();
  const draft=await (await context.request.post(base+'/api/videos',{headers,data:{title:'Unready synthetic fixture'}})).json();
  await page.goto(base+'/watch/'+draft.id);
  await page.getByRole('alert').filter({hasText:'Видео не найдено или недоступно'}).waitFor();
  console.log('OK corrupt processing error and unavailable/unready watch states in Chromium');
  await page.goto(base+'/');
  const cdp=await context.newCDPSession(page);
  await cdp.send('Network.enable');
  await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:0,downloadThroughput:-1,uploadThroughput:64*1024});
  const progress=await page.evaluate(({id,csrf})=>new Promise(resolve=>{
   const xhr=new XMLHttpRequest();let progress=0;
   xhr.open('PUT',`/api/videos/${id}/source`);
   xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-CSRF-Token',csrf);
   xhr.upload.onprogress=()=>progress++;
   xhr.onabort=()=>resolve(progress);
